import {productUrlBuilder, rebuildPathWithParams} from '@salesforce/retail-react-app/app/utils/url'

/**
 * Get the human-friendly version of the variation values that users have selected.
 * Useful for displaying these values in the UI.
 *
 * @param {Object} variationAttributes - The products variation attributes.
 * @param {Object} values - The variations selected attribute values.
 * @returns {Object} - A key value map of the display name and display value.
 *
 * @example
 * const displayValues = getDisplayVariationValues(
 *     [ { "id": "color", "name": "Colour", "values": [ { "name": "royal", "orderable": true, "value": "JJ5FUXX" } ] } ],
 *     { "color": "JJ5FUXX" }
 * )
 * // returns { "Colour": "royal" }
 */
export const getDisplayVariationValues = (variationAttributes, values = {}) => {
    if (!variationAttributes || !Array.isArray(variationAttributes)) {
        return {}
    }

    const returnVal = Object.entries(values).reduce((acc, [id, value]) => {
        const attribute = variationAttributes.find(({id: attributeId}) => attributeId === id)
        if (!attribute || !attribute.values) {
            return acc
        }

        const attributeValue = attribute.values.find(
            ({value: attributeValue}) => attributeValue === value
        )

        if (attributeValue) {
            return {
                ...acc,
                [attribute.name]: attributeValue.name
            }
        }
        return acc
    }, {})
    return returnVal
}

/**
 * Normalizes data for product sets and product bundles into the same format
 * Useful for operations that apply to both product sets and product bundles
 * Creates deep clones of child products to avoid mutation issues
 *
 * @param {Object} product - A product set or product bundle
 * @returns {Object} - returns normalized product if product is a set/bundle, otherwise returns original product
 */
export const normalizeSetBundleProduct = (product) => {
    if (!product?.type.set && !product?.type.bundle) return product

    const childProducts = product?.type.set
        ? product.setProducts.map((child) => {
              return {
                  product: {...child},
                  quantity: null
              }
          })
        : product.bundledProducts.map((child) => {
              return {
                  ...child,
                  product: {...child.product}
              }
          })

    return {
        ...product,
        childProducts
    }
}

/**
 * Creates an array of product items used to update the child variant selections for a product bundle,
 * usually in an updateItemToBasket/updateItemsToBasket shopper baskets API call
 *
 * @param {Object} bundle - A product that is a bundle.
 * @param {Array} childProductSelections - An array of the bundle child products with a selected variant.
 *      Each item in the array should have the product, variant, and quantity.
 * @returns {Array} - an array of bundle child product items that have the updated variant
 */
export const getUpdateBundleChildArray = (bundle, childProductSelections) => {
    const itemsToBeUpdated = []
    bundle?.bundledProductItems?.forEach((bundleChild) => {
        const childSelection = childProductSelections?.find(
            (childProduct) =>
                childProduct.product?.id === bundleChild.productId ||
                childProduct.product?.itemId === bundleChild.itemId
        )

        const selectedProductId = childSelection?.variant?.productId || childSelection?.product?.id

        // only update the item if the selected product is different from what's in the current bundle
        if (childSelection && selectedProductId !== bundleChild.productId) {
            itemsToBeUpdated.push({
                itemId: bundleChild.itemId,
                productId: selectedProductId,
                quantity: childSelection.quantity ?? bundleChild.quantity
            })
        }
    })
    return itemsToBeUpdated
}

/**
 * This function extract the price information of a given product
 * If a product is a master,
 *  currentPrice: get the lowest price (including promotional prices) among variants
 *  listPrice: get the list price of the variant that has lowest price (including promotional price)
 *  maxPrice: the max price in tieredPrices of variant that has lowest price
 * @param {object} product - product detail object
 * @param {object} opts - options to pass into the function like intl, quantity, and currency
 */
export const getPriceData = (product, opts = {}) => {
    const {quantity = 1} = opts
    const isASet = product?.hitType === 'set' || !!product?.type?.set
    const isMaster = product?.hitType === 'master' || !!product?.type?.master
    let currentPrice
    let variantWithLowestPrice
    // grab the variant that has the lowest price (including promotional price)
    if (isMaster) {
        variantWithLowestPrice = findLowestPrice(product)
        currentPrice = variantWithLowestPrice?.minPrice
    } else {
        currentPrice = findLowestPrice(product)?.minPrice
    }

    // since the price is the lowest value among price books, each product will have at lease a single item tiered price at quantity 1
    // the highest value of tieredPrices is presumptively the list price
    const tieredPrices = variantWithLowestPrice?.data?.tieredPrices || product?.tieredPrices || []
    const maxTieredPrice = tieredPrices?.length
        ? Math.max(...tieredPrices.map((item) => item.price))
        : undefined
    const highestTieredPrice = tieredPrices.find((tier) => tier.price === maxTieredPrice)
    const listPrice = highestTieredPrice?.price

    // if a product has tieredPrices, get the tiered that has the higher closest quantity to current quantity
    const filteredTiered = tieredPrices.filter((tiered) => tiered.quantity <= quantity)
    const closestTieredPrice =
        filteredTiered.length &&
        filteredTiered.reduce((prev, curr) => {
            return Math.abs(curr.quantity - quantity) < Math.abs(prev.quantity - quantity)
                ? curr
                : prev
        })
    return {
        currentPrice,
        listPrice,
        pricePerUnit: product?.pricePerUnit,
        isOnSale: currentPrice < listPrice,
        isASet,
        isMaster,
        // For a product, set price is the lowest price of its children, so the price should be considered a range
        // For a master product, when it has more than 2 variants, we use the lowest priced variant, so it is  considered a range price
        //      but for master that has one variant, it is not considered range
        isRange: (isMaster && product?.variants?.length > 1) || isASet || false,
        // priceMax is for product set
        tieredPrice: closestTieredPrice?.price,
        maxPrice: product?.priceMax || maxTieredPrice
    }
}

/**
 * Filters the provided product `ImageGroups` array with the optional filters.
 *
 * @param {ImageGroup[]} imageGroups
 * @param {object} filters
 * @param {string} filters.viewType
 * @param {object} filters.variationValues
 *
 * @returns {ImageGroup[]} filteredImageGroups
 */
export const filterImageGroups = (imageGroups = [], filters) => {
    if (!filters) {
        throw new Error(`Missing required "filters" argument`)
    }

    const {viewType, variationValues = {}} = filters
    // NOTE: For future feature enhancement compatibility we use an object for the `variationValues` as
    // we might want to filter on more than the one attribute id/value pair.
    const [selectedAttributeId, selectedAttributeValue] = Object.entries(variationValues)[0] || []

    // Filters
    const typeFilter = viewType ? (group) => group.viewType === viewType : () => true
    const attributeFilter =
        !!selectedAttributeId && !!selectedAttributeValue
            ? ({variationAttributes = []}) =>
                  variationAttributes.some(
                      ({id, values}) =>
                          id === selectedAttributeId &&
                          !!values.find(({value}) => value === selectedAttributeValue)

/**
 * Shared primitives for the three independent product-card mapping files
 * (`overrides/app/pages/product-list/productListCardMapper.ts`, `overrides/app/utils/recentlyViewedCard.ts`,
 * `overrides/app/utils/recentlyViewedFullHistoryCard.ts`) — each reads a genuinely different input shape
 * (`ProductListSearchHit` from Search vs. `ShopperProductsTypes.Product` from `getProducts`) and produces a
 * genuinely different output scope, so the three top-level mapper functions themselves stay separate. What's
 * here is the handful of primitives that really were byte-identical (or a strict subset) across all three —
 * extracted once nobody was touching the same declared-twice literals/comparators. See CodeRabbit's
 * 2026-09-10 review (the same non-transitive sort bug, independently found in all three copies) and the
 * postbuild UNIFORM finding on the 3-way mapper duplication for the evidence this was worth doing.
 */

/**
 * Extracts the merchandiser-assigned sequence number baked into a catalog image's own filename
 * (e.g. `.../images/1.4673ts251.gvscp.guava-seascape.jpg` → `1`). Returns `undefined` for a
 * non-numeric filename.
 */
const extractImageSequenceNumber = (src: string): number | undefined => {
  const filename = src.split('/').pop() ?? '';
  const match = /^(\d+)\./.exec(filename);
  return match ? Number(match[1]) : undefined;
};

/**
 * Sorts images by their merchandiser-assigned sequence number, leaving any image with no numeric
 * filename in its original slot rather than treating it as equal-to-everything.
 *
 * **Replaces a real, previously-shipped bug** (CodeRabbit, 2026-09-10, found independently in all
 * three of this function's callers): the old comparator returned `0` whenever *either* side lacked
 * a sequence number, which is not a valid total order — `compare(2, unnumbered) === 0`,
 * `compare(unnumbered, 1) === 0`, but `compare(2, 1) === +1` is intransitive, so
 * `Array.prototype.sort` gave engine-dependent, sometimes-wrong results for any mixed
 * numbered/unnumbered set (confirmed live: `['2.a.jpg', 'PRODUCT.PZ.jpg', '1.a.jpg']` sorted to
 * itself, completely unsorted). This version partitions numbered images out, sorts only those by
 * sequence, and re-merges them back into their own original slots — unnumbered images never move.
 *
 * `getSrc` exists because the three call sites don't share one image shape: `recentlyViewedCard.ts`
 * sorts raw SDK `ImageGroup['images']` entries (`disBaseLink`/`link`), the other two sort the
 * simpler `{src, alt}`-shaped `ZimmProductCardImage`. Passing an accessor lets every caller supply
 * its own "how do I read a filename out of this" without forcing a shared shape.
 *
 * @param images the images to sort, in their original (API-returned) order
 * @param getSrc reads the filename-bearing URL out of one image, whatever shape it is
 * @returns a new array — numbered images in ascending sequence order, unnumbered images unchanged
 *   in their original position
 */
export const sortImagesBySequence = <TImage>(
  images: readonly TImage[],
  getSrc: (image: TImage) => string,
): TImage[] => {
  const numbered = images
    .map((image, index) => ({ image, index, sequence: extractImageSequenceNumber(getSrc(image)) }))
    .filter((entry): entry is { image: TImage; index: number; sequence: number } => entry.sequence !== undefined)
    .sort((a, b) => a.sequence - b.sequence);

  const numberedSlots = new Set(numbered.map((entry) => entry.index));
  let next = 0;
  return images.map((image, index) => (numberedSlots.has(index) ? numbered[next++].image : image));
};

/** The one shape this helper needs from a variant — structurally satisfied by both
 *  `ShopperProductsTypes.Variant` and `ShopperSearchTypes.ProductSearchHit`'s own variant shape,
 *  so either can be passed directly with no cast. */
type VariantWithColour = {
  orderable?: boolean;
  variationValues?: Record<string, string | undefined>;
};

/**
 * Resolves a fallback colour from a plain variant list: first orderable variant, else the first
 * variant at all. Returns `undefined` when there are no variants.
 *
 * This is the fallback tail shared, byte-for-byte, by `recentlyViewedCard.ts`'s and
 * `recentlyViewedFullHistoryCard.ts`'s own `resolveViewedColour` (their *entire* colour-resolution
 * strategy — a plain `getProducts`-sourced `Product` has no `representedProduct` field to try
 * first) and by `productListCardMapper.ts`'s own `resolveRepresentativeColour` (its fallback once
 * a `representedProduct` match isn't available — that extra first branch only exists there because
 * Search hits carry that field and `getProducts` results don't, so it stays local to that file
 * rather than being folded in here).
 *
 * @param variants the product's variants, in API order
 * @param colourAttributeId the variation-attribute id to read off the resolved variant (each
 *   caller's own `COLOUR_VARIATION_ATTRIBUTE_ID` constant — always `'color'` today, passed
 *   explicitly rather than hardcoded here so this stays a generic variant-resolution primitive)
 */
export const resolveFallbackColour = (
  variants: readonly VariantWithColour[] | undefined,
  colourAttributeId: string,
): string | undefined => {
  const fallbackVariant = variants?.find((variant) => variant.orderable) ?? variants?.[0];
  return fallbackVariant?.variationValues?.[colourAttributeId];
};

/**
 * The "gallery position" alt-text convention: a missing/empty alt is left empty, not defaulted to
 * anything — matching base SFCC's own decorative-image convention for a non-primary gallery
 * image. Shared, byte-identical, by `productListCardMapper.ts`'s and
 * `recentlyViewedFullHistoryCard.ts`'s own `toCardImage`.
 */
export const toGalleryAlt = (alt: string | undefined): string => alt ?? '';

/**
 * The "required position" alt-text convention — for the one primary/hero image a screen reader
 * announces first, a missing OR whitespace-only alt falls back to the product name rather than
 * rendering an effectively blank accessible name. Used by `recentlyViewedCard.ts` (its only image
 * is always this position) and `recentlyViewedFullHistoryCard.ts`'s primary image.
 *
 * **Fixes a real, previously-shipped gap** (found verifying this exact extraction, 2026-09-10):
 * `recentlyViewedFullHistoryCard.ts`'s own version of this check was `alt || product.name`, with
 * no `.trim()` — despite its own comment claiming to mirror `recentlyViewedCard.ts`'s version
 * "exactly." A whitespace-only alt (`'   '`) is a non-empty string, so it passed straight through
 * instead of falling back — confirmed with a real repro: the two versions produced different
 * output (`'Fallback Name'` vs `'   '`) for the identical input.
 */
export const resolveRequiredAlt = (alt: string | undefined, fallbackName: string): string =>
  alt?.trim() || fallbackName;

