/**
 * THROWAWAY verification script — NOT part of the codebase. Written to check E2's real code path
 * (selectRecentlyViewedFullHistoryCard / resolveOrderableVariant / the recentlyViewed container's
 * own onAddToBag fallback expression) against a realistically Einstein-hydrated rec object. This
 * file will be deleted before the session ends; it is not a permanent addition.
 */
import { describe, test, expect } from 'vitest';
import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
import {
  selectRecentlyViewedFullHistoryCard,
  resolveOrderableVariant,
} from './recentlyViewedFullHistoryCard';
import type { RecentlyViewedFullHistoryProduct } from './recentlyViewedFullHistoryCard';

const formatPrice = (amount: number, currency: string) => `${currency} ${amount.toFixed(2)}`;

describe('SCRATCH: realistic Einstein-hydrated fixture', () => {
  test('step 1 — replicates fetchRecProductDetails\' own merge expression verbatim (use-einstein.js:497-505)', () => {
    // Raw Einstein rec — only what Einstein itself returns for a recommendation entry.
    const rec = {
      id: 'PROD001M',
      imageUrl: 'https://einstein.example.com/thumb/prod001.jpg',
      productName: 'Feather Trim Mini Dress',
      // Einstein's own recommendation-time price estimate -- deliberately DIFFERENT from the
      // hydrated product's own `price` below, to prove which one wins the spread.
      price: 999,
    };
    // The hydrated getProducts() result for the SAME id (this is what products.data.find(...) found).
    const hydratedProduct = {
      id: 'PROD001M',
      name: 'Feather Trim Mini Dress',
      price: 450,
      currency: 'AUD',
    };

    // Verbatim copy of use-einstein.js's own per-rec .map() body (lines 497-505):
    const merged = {
      ...rec,
      ...hydratedProduct,
      productId: rec.id,
      image: { disBaseLink: rec.imageUrl, alt: rec.productName },
    };

    // id and productId can never disagree, because fetchRecProductDetails only reaches this map
    // step for recs that survived `products.data.find(product => product.id === rec.id)` --
    // by construction, product.id === rec.id whenever this line runs.
    expect(merged.id).toBe('PROD001M');
    expect(merged.productId).toBe('PROD001M');
    expect(merged.id).toBe(merged.productId);

    // The hydrated product's fields win over raw Einstein fields on any name collision (`...product`
    // spreads after `...rec`) -- e.g. `price` here is 450 (hydrated), never 999 (Einstein's guess).
    expect(merged.price).toBe(450);
  });

  const product: RecentlyViewedFullHistoryProduct = {
    id: 'PROD001M',
    name: 'Feather Trim Mini Dress',
    currency: 'AUD',
    // Deliberately NOT equal to any variant price below (399/420) or to the tiered "list" price
    // (550) -- a real master-level flat `price` field has no defined relationship to any of those,
    // see step 4 below.
    price: 450,
    type: { master: true },
    master: { masterId: 'PROD001M', orderable: true },
    variants: [
      {
        productId: 'PROD001M-XS',
        price: 399,
        orderable: true,
        variationValues: { size: 'XS' },
        tieredPrices: [
          { price: 399, quantity: 1 },
          { price: 550, quantity: 1 },
        ],
      } as never,
      {
        productId: 'PROD001M-S',
        price: 420,
        orderable: true,
        variationValues: { size: 'S' },
      } as never,
    ],
    variationAttributes: [
      {
        id: 'size',
        name: 'Size',
        values: [
          { value: 'XS', name: 'XS', orderable: true },
          { value: 'S', name: 'S', orderable: true },
        ],
      },
    ],
    imageGroups: [
      {
        viewType: 'medium',
        images: [
          {
            disBaseLink: 'https://img.zimmermann.com/images/1.prod001.dress.jpg',
            link: 'https://img.zimmermann.com/images/1.prod001.dress.jpg',
            alt: 'Feather Trim Mini Dress, front',
          },
          {
            disBaseLink: 'https://img.zimmermann.com/images/2.prod001.dress.jpg',
            link: 'https://img.zimmermann.com/images/2.prod001.dress.jpg',
            alt: 'Feather Trim Mini Dress, back',
          },
        ],
      },
    ],
    // Einstein-only synthesized field (fetchRecProductDetails) -- included for realism; the mapper
    // never reads this (it reads imageGroups only), so it should have zero effect on the output.
    image: { disBaseLink: 'https://einstein.example.com/thumb/prod001.jpg', alt: 'Feather Trim Mini Dress' } as never,
  };

  test('step 3a — selectRecentlyViewedFullHistoryCard returns a real, fully-populated card (not null, not gated out)', () => {
    const card = selectRecentlyViewedFullHistoryCard(product, formatPrice);

    expect(card).not.toBeNull();
    expect(card?.id).toBe('PROD001M');
    expect(card?.name).toBe('Feather Trim Mini Dress');
    expect(card?.primaryImage?.src).toBe('https://img.zimmermann.com/images/1.prod001.dress.jpg');
    expect(card?.images).toHaveLength(2);
    expect(card?.hoverImage?.src).toBe('https://img.zimmermann.com/images/2.prod001.dress.jpg');
    expect(card?.sizeChipValues).toHaveLength(2);
    expect(card?.isUnavailable).toBe(false);

    // The mapper's own getPriceData-derived price -- this is what the shopper actually sees.
    // findLowestPrice scans variants for a master, so the lowest (XS, 399) wins, with its own
    // tieredPrices producing a real was/now pair (550 -> 399).
    expect(card?.currentPrice).toBe('AUD 399.00');
    expect(card?.originalPrice).toBe('AUD 550.00');

    // Cross-check against getPriceData directly rather than trusting hand-derived numbers alone.
    const priceData = getPriceData(product);
    expect(priceData.currentPrice).toBe(399);
    expect(priceData.listPrice).toBe(550);
    expect(priceData.isOnSale).toBe(true);
  });

  test('step 3b — resolveOrderableVariant resolves the correct, distinct variant for each size (no field mixup)', () => {
    const xs = resolveOrderableVariant(product, 'XS');
    const s = resolveOrderableVariant(product, 'S');

    expect(xs).toEqual({ productId: 'PROD001M-XS', price: 399, orderable: true });
    expect(s).toEqual({ productId: 'PROD001M-S', price: 420, orderable: true });
    // Genuinely different resolved values -- proves this isn't coincidentally passing on identical
    // fixture data for both sizes.
    expect(xs?.productId).not.toBe(s?.productId);
    expect(xs?.price).not.toBe(s?.price);
  });

  test('step 3c — the container\'s own literal fallback expression, evaluated against this fixture', () => {
    // Verbatim copy of index.tsx's own onAddToBag body:
    //   const resolved = selectedSizeChipValue ? resolveOrderableVariant(product, selectedSizeChipValue) : null;
    //   handleResolvedAddToBag(resolved?.productId ?? product.id, resolved?.price ?? product.price);

    // Case A: no size selected.
    const selectedSizeChipValueA: string | undefined = undefined;
    const resolvedA = selectedSizeChipValueA
      ? resolveOrderableVariant(product, selectedSizeChipValueA)
      : null;
    const sentIdA = resolvedA?.productId ?? product.id;
    const sentPriceA = resolvedA?.price ?? product.price;

    // product.id is genuinely present and correct (not shadowed by productId/image) -- confirms
    // this half of the fallback is sound.
    expect(sentIdA).toBe('PROD001M');

    // product.price (450) is NOT what the shopper was shown (399, "AUD 399.00" on the card) and
    // has no defined relationship to it -- findLowestPrice/getPriceData never reads product.price
    // for a master product at all (it only reads product.variants[].price), so this flat field is
    // architecturally decoupled from the true current price for exactly the product shape (a
    // sized master) this fixture -- and any real Zimmermann apparel item -- has.
    expect(sentPriceA).toBe(450);
    const priceData = getPriceData(product);
    expect(sentPriceA).not.toBe(priceData.currentPrice); // 450 !== 399

    // Case A2: same fixture, but with the flat `price` field entirely absent -- also realistic,
    // since SFCC's own per-master pricing commonly lives at product.master.price, not product.price.
    const { price: _omitted, ...productWithNoFlatPrice } = product;
    const sentPriceA2 = (null as { price?: number } | null)?.price ?? productWithNoFlatPrice.price;
    expect(sentPriceA2).toBeUndefined();

    // Case B: a size IS selected, and resolves to a real variant.
    const selectedSizeChipValueB = 'S';
    const resolvedB = selectedSizeChipValueB
      ? resolveOrderableVariant(product, selectedSizeChipValueB)
      : null;
    const sentIdB = resolvedB?.productId ?? product.id;
    const sentPriceB = resolvedB?.price ?? product.price;

    expect(sentIdB).toBe('PROD001M-S');
    expect(sentPriceB).toBe(420); // the S variant's own flat price -- correct for THIS variant,
    // modulo any variant-level productPromotions, which resolveOrderableVariant also does not
    // consult (same class of gap as Case A, smaller blast radius).
  });
});
